package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Boolean;
    attribute welcomeActive : Boolean := false;
    perform action tick {
      first start;
      then if ((io_1) and (((io_0) <= (10.0)))) {
        first start;
        then assign welcomeActive := true;
      } else {
        first start;
        then assign welcomeActive := false;
      }
    }
    out attribute io_2 : Boolean = (if welcomeActive ? true else false);
    out attribute io_3 : Integer = (if welcomeActive ? 1000 else 0);
    out attribute serial_0_trigger : Boolean = (if welcomeActive ? true else false);
    out attribute serial_0_value_0 : Integer = (if welcomeActive ? 1 else 0);
  }
  part system : Controller;
}
